import React, { useState } from 'react';
import axios from 'axios';
import { Database, CheckCircle } from 'lucide-react';

const ProductUpload = () => {
  const [file, setFile] = useState(null);
  const [uploading, setUploading] = useState(false);
  const [successMsg, setSuccessMsg] = useState('');

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
      setSuccessMsg('');
    }
  };

  const handleUpload = async () => {
    if (!file) return;

    const formData = new FormData();
    formData.append('file', file);

    setUploading(true);
    try {
      const response = await axios.post('http://localhost:5000/api/products/upload', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
      setSuccessMsg(response.data.message);
      setFile(null);
    } catch (error) {
      console.error('Error uploading product file:', error);
      alert('حدث خطأ أثناء رفع ملف المنتجات');
    } finally {
      setUploading(false);
    }
  };

  const handleDeleteMaster = async () => {
    if (window.confirm('هل أنت متأكد أنك تريد مسح جميع بيانات المنتجات (Master Data)؟')) {
      try {
        await axios.delete('http://localhost:5000/api/products/all');
        setSuccessMsg('تم مسح جميع بيانات الماستر بنجاح.');
      } catch (error) {
        console.error('Error deleting master data:', error);
        alert('حدث خطأ أثناء مسح البيانات');
      }
    }
  };

  return (
    <div className="bg-white rounded-2xl shadow-sm border border-slate-100 p-6 flex flex-col justify-center mt-6">
      <div className="flex items-center gap-2 mb-4">
        <Database className="w-5 h-5 text-emerald-500" />
        <h3 className="text-lg font-semibold text-slate-800">تحديث CBM المنتجات (Master Data)</h3>
      </div>

      <div className="flex items-center gap-4">
        <div className="flex-1">
          <label className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-lg file:border-0 file:text-sm file:font-semibold file:bg-emerald-50 file:text-emerald-700 hover:file:bg-emerald-100 cursor-pointer border border-slate-200 rounded-lg p-1">
            <input 
              type="file" 
              accept=".csv, application/vnd.openxmlformats-officedocument.spreadsheetml.sheet, application/vnd.ms-excel" 
              onChange={handleFileChange}
              disabled={uploading}
              className="w-full"
            />
          </label>
        </div>

        <button
          onClick={handleUpload}
          disabled={!file || uploading}
          className={`py-2.5 px-6 rounded-lg text-white font-medium transition-all flex-shrink-0 ${
            !file || uploading 
              ? 'bg-slate-300 cursor-not-allowed' 
              : 'bg-emerald-600 hover:bg-emerald-700 shadow-md hover:shadow-emerald-200'
          }`}
        >
          {uploading ? 'جاري الرفع...' : 'رفع البيانات'}
        </button>

        <button
          onClick={handleDeleteMaster}
          className="py-2.5 px-4 rounded-lg text-red-600 bg-red-50 hover:bg-red-100 font-medium transition-all border border-red-200 flex-shrink-0"
          title="مسح الماستر بالكامل"
        >
          مسح الماستر
        </button>
      </div>

      {successMsg && (
        <div className="mt-3 flex items-center gap-2 text-emerald-600 text-sm font-medium">
          <CheckCircle className="w-4 h-4" />
          {successMsg}
        </div>
      )}
    </div>
  );
};

export default ProductUpload;
